def rrf(result_lists, k=60):
    scores = {}
    for results in result_lists:            # e.g. [dense_ids, sparse_ids]
        for rank, doc_id in enumerate(results):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    # higher fused score = ranked well by one or both retrievers
    return sorted(scores, key=scores.get, reverse=True)

fused = rrf([["a", "b", "c"], ["c", "a", "z"]])
print(fused)   # 'a' and 'c' rise: they rank well in both lists

