def rrf(result_lists, k=60):
    scores = {}
    for results in result_lists:
        for rank, doc_id in enumerate(results):        # rank is 0-based
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda kv: kv[1], reverse=True)

# dense and sparse disagree on order and each surfaces a unique doc
dense_order = ["d_auth", "d_reset", "d_e1042"]   # exact-code doc ranked low
sparse_order = ["d_e1042", "d_auth", "d_billing"]  # exact-code doc ranked top

fused = rrf([dense_order, sparse_order], k=60)
for doc_id, score in fused:
    print(doc_id, round(score, 5))
